-- Add storage policies for page_assets bucket
CREATE POLICY "Anyone can read page assets"
  ON storage.objects FOR SELECT
  USING (bucket_id = 'page_assets');

CREATE POLICY "Authenticated users can upload page assets"
  ON storage.objects FOR INSERT
  WITH CHECK (
    bucket_id = 'page_assets' 
    AND auth.role() = 'authenticated'
  );

CREATE POLICY "Authenticated users can update page assets"
  ON storage.objects FOR UPDATE
  USING (
    bucket_id = 'page_assets' 
    AND auth.role() = 'authenticated'
  );

CREATE POLICY "Authenticated users can delete page assets"
  ON storage.objects FOR DELETE
  USING (
    bucket_id = 'page_assets' 
    AND auth.role() = 'authenticated'
  );

-- Fonction pour permettre aux utilisateurs de supprimer leur propre compte
CREATE OR REPLACE FUNCTION delete_own_account()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  user_id uuid;
BEGIN
  -- Récupérer l'ID de l'utilisateur connecté
  user_id := auth.uid();

  -- Vérifier que l'utilisateur est connecté
  IF user_id IS NULL THEN
    RAISE EXCEPTION 'Non authentifié';
  END IF;

  -- Supprimer les données de l'utilisateur dans user_roles
  DELETE FROM user_roles WHERE user_roles.user_id = user_id;

  -- Supprimer l'utilisateur de auth.users
  DELETE FROM auth.users WHERE id = user_id;
END;
$$;

-- Donner les permissions aux utilisateurs authentifiés
GRANT EXECUTE ON FUNCTION delete_own_account() TO authenticated;

-- Mise à jour de la fonction pour supprimer aussi le profil
CREATE OR REPLACE FUNCTION delete_own_account()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  user_id uuid;
BEGIN
  -- Récupérer l'ID de l'utilisateur connecté
  user_id := auth.uid();

  -- Vérifier que l'utilisateur est connecté
  IF user_id IS NULL THEN
    RAISE EXCEPTION 'Non authentifié';
  END IF;

  -- Supprimer le profil de l'utilisateur
  DELETE FROM profiles WHERE id = user_id;

  -- Supprimer les données de l'utilisateur dans user_roles
  DELETE FROM user_roles WHERE user_roles.user_id = user_id;

  -- Supprimer l'utilisateur de auth.users
  DELETE FROM auth.users WHERE id = user_id;
END;
$$;

