-- Add link_label column to featured_highlights
ALTER TABLE public.featured_highlights
ADD COLUMN IF NOT EXISTS link_label TEXT;

-- Add end_date column to featured_highlights
ALTER TABLE public.featured_highlights
ADD COLUMN end_date TIMESTAMP WITH TIME ZONE;

-- Create index for better performance when filtering expired highlights
CREATE INDEX IF NOT EXISTS featured_highlights_end_date_idx ON public.featured_highlights(end_date);

-- Update the public view policy to exclude expired highlights
DROP POLICY IF EXISTS "Featured highlights are viewable by everyone" ON public.featured_highlights;

CREATE POLICY "Featured highlights are viewable by everyone"
  ON public.featured_highlights
  FOR SELECT
  USING (
    is_active = true 
    AND (end_date IS NULL OR end_date > NOW())
  );

ALTER TABLE public.featured_highlights ADD COLUMN start_date TIMESTAMP WITH TIME ZONE;

CREATE INDEX IF NOT EXISTS featured_highlights_start_date_idx ON public.featured_highlights(start_date);

DROP POLICY IF EXISTS "Featured highlights are viewable by everyone" ON public.featured_highlights;

CREATE POLICY "Featured highlights are viewable by everyone" ON public.featured_highlights FOR SELECT USING (is_active = true AND (start_date IS NULL OR start_date <= NOW()) AND (end_date IS NULL OR end_date > NOW()));

-- Update counselor policies to allow admin access to inactive records and ensure updates succeed
DROP POLICY IF EXISTS "Anyone can view counselors" ON counselors;

CREATE POLICY "Public can view active counselors"
  ON counselors FOR SELECT
  USING (is_active = true);

