CREATE OR REPLACE FUNCTION set_page_order_index()
RETURNS trigger AS $$
DECLARE
  max_order INTEGER;
BEGIN
  IF NEW.order_index IS NULL THEN
    SELECT COALESCE(MAX(order_index), -1) + 1 INTO max_order
    FROM pages
    WHERE (parent_id IS NOT DISTINCT FROM NEW.parent_id);

    NEW.order_index := max_order;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS pages_order_index_trigger ON pages;

CREATE TRIGGER pages_order_index_trigger
BEFORE INSERT ON pages
FOR EACH ROW
EXECUTE FUNCTION set_page_order_index();

-- Créer la table pour stocker les scores du jeu
CREATE TABLE IF NOT EXISTS game_scores (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  player_name VARCHAR(3) NOT NULL,
  score INTEGER NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Créer un index sur le score pour les requêtes de classement
CREATE INDEX IF NOT EXISTS idx_game_scores_score ON game_scores(score DESC);

-- Créer un index sur created_at pour les requêtes récentes
CREATE INDEX IF NOT EXISTS idx_game_scores_created_at ON game_scores(created_at DESC);

-- Activer RLS (Row Level Security)
ALTER TABLE game_scores ENABLE ROW LEVEL SECURITY;

-- Politique : tout le monde peut lire les scores
CREATE POLICY "Anyone can read game scores" ON game_scores
  FOR SELECT
  USING (true);

-- Politique : tout le monde peut insérer des scores
CREATE POLICY "Anyone can insert game scores" ON game_scores
  FOR INSERT
  WITH CHECK (true);

-- Add password_set column to profiles table to track if user has set their password
ALTER TABLE profiles
  ADD COLUMN IF NOT EXISTS password_set boolean DEFAULT false;

-- Set password_set to true for existing users (they already have passwords)
UPDATE profiles
SET password_set = true
WHERE password_set IS NULL OR password_set = false;

-- Ensure default value is false for new rows
ALTER TABLE profiles
  ALTER COLUMN password_set SET DEFAULT false;
